import assert from "node:assert/strict";
import { findConflicts } from "./src/booking-conflicts.js";

const T = (id, room, start, end) => ({ id, room, start, end });
const s = "2026-03-01T09:00:00Z", e = "2026-03-01T10:00:00Z";

// R1
assert.throws(() => findConflicts("nope"), TypeError);
assert.throws(() => findConflicts(null), TypeError);
assert.throws(() => findConflicts([{...T("a","R",s,e), id: ""}]), TypeError);
assert.throws(() => findConflicts([{...T("a","R",s,e), room: 5}]), TypeError);
assert.throws(() => findConflicts([{...T("a","R",s,e), start: "2026-03-01 09:00:00Z"}]), TypeError);
assert.throws(() => findConflicts([{...T("a","R",s,e), end: "2026-02-30T10:00:00Z"}]), TypeError);
assert.throws(() => findConflicts([{...T("a","R",s,e), end: "2026-13-01T10:00:00Z"}]), TypeError);
assert.throws(() => findConflicts([42]), TypeError);
// R2
assert.throws(() => findConflicts([T("a","R",e,s)]), RangeError);
assert.throws(() => findConflicts([T("a","R",s,s)]), RangeError);
assert.throws(() => findConflicts([T("a","R",s,e), T("a","R","2026-03-02T09:00:00Z","2026-03-02T10:00:00Z")]), TypeError);
// R3 ordering: second booking has bad end AND duplicate id -> RangeError (end check before dup check)
assert.throws(() => findConflicts([T("a","R",s,e), T("a","R",e,s)]), RangeError);
// R3: booking[1] malformed start, booking[2] would duplicate -> TypeError from booking[1] first
assert.throws(() => findConflicts([T("a","R",s,e), {id:"b",room:"R",start:"bogus",end:e}, T("a","R",s,e)]), TypeError);
// R4
assert.deepEqual(findConflicts([T("a","R",s,e), T("b","R",e,"2026-03-01T11:00:00Z")]), []); // touching
assert.deepEqual(findConflicts([T("a","R",s,e), T("b","R",s,e)]), [["a","b"]]); // identical
assert.deepEqual(findConflicts([T("a","R","2026-03-01T08:00:00Z","2026-03-01T12:00:00Z"), T("b","R",s,e)]), [["a","b"]]); // inside
assert.deepEqual(findConflicts([T("a","A1",s,e), T("b","a1",s,e)]), []); // case-sensitive rooms
// R5 ordering: sort by idA then idB, idA<idB
const input = [T("z","R","2026-03-01T00:00:00Z","2026-03-02T00:00:00Z"),
               T("b","R","2026-03-01T00:00:00Z","2026-03-02T00:00:00Z"),
               T("a","R","2026-03-01T00:00:00Z","2026-03-02T00:00:00Z"),
