assert.deepEqual(findConflicts(input), [["a","b"],["a","m"],["a","z"],["b","m"],["b","z"],["m","z"]]);
assert.deepEqual(findConflicts([]), []);
// R6: deep-frozen input, array order preserved
const frozen = Object.freeze([T("b","R1","2026-03-01T09:00:00Z","2026-03-01T10:00:00Z"),
                               T("a","R1","2026-03-01T09:30:00Z","2026-03-01T11:00:00Z")]);
frozen.forEach(Object.freeze);
assert.deepEqual(findConflicts(frozen), [["a","b"]]);
assert.deepEqual(frozen, [frozen[0], frozen[1]]);
console.log("all sanity checks passed");
'
